## 5️⃣ TL;DR code you can copy-paste

```kotlin
// ---- 1. Put this in Application.onCreate() or before the first MapView ----
val stock = MapLibre.getModuleProvider()

class VaultHttpRequest(private val stock: HttpRequest) : HttpRequest {
    override fun executeRequest(
        responder: HttpResponder,
        nativePtr: Long,
        resourceUrl: String,
        dataRange: String?,
        etag: String?,
        modified: String?,
        offlineUsage: Boolean
    ) {
        if (!resourceUrl.startsWith("vault://")) {
            // Let the default implementation handle everything else
            return stock.executeRequest(
                responder, nativePtr, resourceUrl,
                dataRange, etag, modified, offlineUsage
            )
        }

        try {
            val bytes = Vault.decryptTile(resourceUrl)   // <-- your own code
            responder.onResponse(200, null, null, null, null, null, null, bytes)
        } catch (e: Exception) {
            responder.handleFailure(HttpRequest.CONNECTION_ERROR, e.message ?: "Vault error")
        }
    }

    override fun cancelRequest() = stock.cancelRequest()
}

// Install the wrapper
MapLibre.setModuleProvider(object : ModuleProvider by stock {
    override fun createHttpRequest(): HttpRequest = VaultHttpRequest(stock.createHttpRequest())
})
```

That’s it – the rest of your app can stay exactly the same as a normal MapLibre-Native map. The style can reference `vault://…` URLs, and each tile will be decrypted on-the-fly.

