Below is a **complete, self-contained TypeScript example** that

1. **creates an IndexedDB database** (`tile-cache`) and a single object store (`tiles`);
2. **registers a custom protocol** `cache://` with `maplibregl.addProtocol`;
3. **looks up a tile in IndexedDB**, falls back to the network if it isn’t cached, and stores the fetched tile for the next request;
4. **creates a MapLibre GL JS map** whose style can reference tiles as `cache://tiles/{z}/{x}/{y}`.

> **Important** – `addProtocol` is **promise-based** (available since MapLibre GL JS v4.0.0).  
> The function you register must return a `Promise<ProtocolResponse>` where `ProtocolResponse` is either an `ArrayBuffer` (the raw tile data) **or** an object `{ data: ArrayBuffer, cacheControl?: string, expires?: string, ... }`.

---

## 1️⃣  IndexedDB helper (tiny wrapper)

```ts
// idb.ts – a very small wrapper around IndexedDB
export interface TileKey {
  z: number;
  x: number;
  y: number;
}

/** Open (or create) the DB. Returns a promise that resolves to the DB instance. */
export function openTileCacheDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('tile-cache', 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      // One object store, key = `${z}/${x}/${y}`
      db.createObjectStore('tiles');
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

/** Get a tile from the DB. Returns undefined if not present. */
export async function getTileFromCache(
  db: IDBDatabase,
  { z, x, y }: TileKey
): Promise<ArrayBuffer | undefined> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction('tiles', 'readonly');
    const store = tx.objectStore('tiles');
    const getReq = store.get(`${z}/${x}/${y}`);
    getReq.onsuccess = () => resolve(getReq.result as ArrayBuffer | undefined);
    getReq.onerror = () => reject(getReq.error);
  });
}

/** Store a tile in the DB. */
export async function putTileInCache(
  db: IDBDatabase,
  { z, x, y }: TileKey,
  data: ArrayBuffer
): Promise<void> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction('tiles', 'readwrite');
    const store = tx.objectStore('tiles');
    const putReq = store.put(data, `${z}/${x}/${y}`);
    putReq.onsuccess = () => resolve();
    putReq.onerror = () => reject(putReq.error);
  });
}
```

