## 2️⃣  Register the `cache://` protocol

```ts
// protocol.ts
import maplibregl, { ProtocolResponse } from 'maplibre-gl';
import { openTileCacheDB, getTileFromCache, putTileInCache, TileKey } from './idb';

// Keep a single DB instance for the whole page
let dbPromise: Promise<IDBDatabase> | null = null;
function getDB(): Promise<IDBDatabase> {
  if (!dbPromise) dbPromise = openTileCacheDB();
  return dbPromise;
}

/**
 * The handler that MapLibre will call for every URL that starts with
 * `cache://`.  The `params` argument contains the original URL and the
 * parsed `{z, x, y}` values (if the URL matches the pattern we gave it).
 */
async function cacheProtocolHandler(
  params: maplibregl.ProtocolParams
): Promise<ProtocolResponse> {
  // 1️⃣  Parse the tile coordinates from the URL.
  //    Expected pattern: cache://tiles/{z}/{x}/{y}
  const match = params.url.match(/^cache:\/\/tiles\/(\d+)\/(\d+)\/(\d+)$/);
  if (!match) {
    // If the URL does not match our pattern we can reject it – MapLibre will
    // try the next protocol (or fail).
    return Promise.reject(new Error(`Invalid cache URL: ${params.url}`));
  }

  const [, zStr, xStr, yStr] = match;
  const tileKey: TileKey = {
    z: Number(zStr),
    x: Number(xStr),
    y: Number(yStr),
  };

  const db = await getDB();

  // 2️⃣  Try the cache first.
  const cached = await getTileFromCache(db, tileKey);
  if (cached) {
    // Return the raw ArrayBuffer – MapLibre will treat it as an MVT tile.
    return cached;
  }

  // 3️⃣  Not cached → fetch from the network (you can point to any remote source).
  //     In this example we assume the original source lives at
  //     https://example.com/tiles/{z}/{x}/{y}.pbf
  const remoteUrl = `https://example.com/tiles/${tileKey.z}/${tileKey.x}/${tileKey.y}.pbf`;
  const response = await fetch(remoteUrl);
  if (!response.ok) {
    throw new Error(`Network error ${response.status} for ${remoteUrl}`);
  }
  const arrayBuffer = await response.arrayBuffer();

  // 4️⃣  Store it for next time (fire-and-forget, we don’t block the UI).
  putTileInCache(db, tileKey, arrayBuffer).catch(console.error);

  // 5️⃣  Return the data to MapLibre.
  return arrayBuffer;
}

/**
 * Register the protocol **once**, before any MapLibre map is created.
 */
export function registerCacheProtocol(): void {
  // The second argument is the handler; the third argument is an optional
  // pattern that tells MapLibre which URLs should be routed to this handler.
  // Using a RegExp is optional – you could also just register the scheme
  // and parse the URL yourself (as we do above).
  maplibregl.addProtocol('cache', cacheProtocolHandler);
}
```

